const F = window.RollandsFinance;
const ledgerFilters = {
  customer: { status: 'all', period: '', party: '', partyNumber: '', search: '' },
  supplier: { status: 'all', period: '', party: '', search: '' }
};
let navOpen = false;
let quickSearch = '';
let invoiceFilter = 'all';
let invoiceSearch = '';
let showAllPriorities = false;
let ledgerSection = 'journal';
let ledgerSearch = '';
let batchSearch = '';
const ledgerSort = { customer: { key: 'invoiceDate', dir: 'desc' }, supplier: { key: 'invoiceDate', dir: 'desc' } };
const ledgerColumns = { customer: Array(13).fill(true), supplier: Array(13).fill(true) };
let activeContextMenu = null;
let directorySearch = { customer: '', supplier: '' };

function navigate(destination, filter) {
  view = destination === 'website' ? 'public' : 'admin';
  page = destination === 'website' ? 'overview' : destination;
  if (filter && ['receivables', 'payables'].includes(destination)) ledgerFilters[destination === 'receivables' ? 'customer' : 'supplier'] = {status:filter,period:'',party:'',partyNumber:'',search:''};
  activeModal = null; navOpen = false; quickSearch = '';
  const hash = '#/' + destination;
  if (location.hash !== hash) history.pushState(null, '', hash);
  render();
  window.scrollTo({ top: 0, behavior: 'instant' });
}
function workspaceChrome(content) {
  const groups = [
    ['Arbetsyta', [['overview', 'Översikt'], ['review', 'Granska & åtgärda']]],
    ['Försäljning', [['customers', 'Kunder'], ['receivables', 'Kundreskontra'], ['res-tools', 'Reskontraverktyg'], ['invoices', 'Kundfakturor']]],
    ['Inköp', [['vendors', 'Leverantörer'], ['inbox', 'Fakturainkorg'], ['payables', 'Leverantörsreskontra'], ['supplier', 'Leverantörsfakturor']]],
    ['Ekonomi', [['bank', 'Bank & avstämning'], ['ledger', 'Bokföring'], ['batches', 'Buntar'], ['accounts', 'Kontoplan'], ['reports', 'Rapporter'], ['audit', 'Revisionslogg'], ['assistant', 'Hjälp & chatbot'], ['settings', 'Inställningar']]]
  ];
  const icons = { ...icon, customers:'♙', vendors:'♟', inbox:'⇩', receivables: '↗', 'res-tools': '⇄', payables: '↙', batches: '▤', accounts: '≡', reports: '▥', audit: '◷', assistant: '?' };
  const names = Object.fromEntries(groups.flatMap(g => g[1]));
  const nav = groups.map(([group, links]) => `<div class="nav-group"><p>${group}</p>${links.map(([key,label]) => `<button data-action="nav" data-page="${key}" class="${page === key ? 'active' : ''}" ${page === key ? 'aria-current="page"' : ''}><span class="nav-ico" aria-hidden="true">${icons[key]}</span>${label}${key === 'review' && reviewCount() ? `<span class="nav-count">${reviewCount()}</span>` : ''}</button>`).join('')}</div>`).join('');
  const contextMenu = activeContextMenu ? `<div class="context-menu" style="left:${activeContextMenu.x}px;top:${activeContextMenu.y}px" role="menu"><button data-action="export-context" data-kind="${escapeHtml(activeContextMenu.kind)}" data-party="${escapeHtml(activeContextMenu.party || '')}" data-party-number="${escapeHtml(activeContextMenu.partyNumber || '')}">↓ Exportera segment till Excel</button><button data-action="close-context-menu">Avbryt</button></div>` : '';
  return `<div class="admin-shell ${navOpen ? 'nav-open' : ''}"><aside class="sidebar" id="main-menu"><div class="admin-brand"><a class="brand" href="#/overview" data-action="nav" data-page="overview">Rollands<small>EKONOMI & VERKSAMHET</small></a></div><div class="company-chip">${escapeHtml(state.business.name)}<br>${escapeHtml(state.business.orgNumber)}</div><nav class="side-nav" aria-label="Administration">${nav}</nav><div class="sidebar-foot"><button class="site-link" data-action="public">↗ Visa företagets hemsida</button><span class="demo-dot"></span> ${typeof demoMode !== 'undefined' && demoMode ? 'Delad demo – sparas i denna webbläsare' : 'Lokal utvecklingsversion'}</div></aside><section class="admin-main"><header class="admin-top"><div class="header-left"><button class="menu-toggle button ghost sm" data-action="toggle-nav" aria-controls="main-menu" aria-expanded="${navOpen}">☰ Meny</button><div class="crumb">Arbetsyta <span>/</span> <strong>${names[page] || 'Översikt'}</strong></div></div><div class="top-actions"><button class="search-trigger" data-action="global-search" aria-label="Sök kund, leverantör eller faktura">⌕ <span>Sök i plattformen</span><kbd>Ctrl K</kbd></button><button class="button sm" data-action="new-invoice">+ Ny faktura</button><div class="user" aria-label="Administratör">RS</div></div></header><main class="content">${content}</main><div class="demo-footer">Utvecklingsversion · PDF-fakturor kan skapas och laddas ned. E-post, bankhämtning och AI kräver produktionsanslutning.</div></section></div>${contextMenu}`;
}
function statCard(label, value, detail, destination, filter, accent = '') {
  return `<button class="metric stat-button ${accent}" data-action="drill" data-page="${destination}" data-filter="${filter || 'all'}"><span class="label">${label}<span aria-hidden="true">↗</span></span><span class="number">${value}</span><span class="sub">${detail}</span></button>`;
}
function commandCenter() {
  const d = F.dashboard(state);
  const count = d.priorities.length;
  const coverage = d.bankCount ? Math.round(d.handled / d.bankCount * 100) : 0;
  const flowHealth = d.flowHealth;
  const flowWarnings = [flowHealth.bank.warning ? `<article class="flow-health warning"><b>Bankflöde stannat</b><span>${escapeHtml(flowHealth.bank.message)}</span><small>Senaste import: ${escapeHtml(flowHealth.bank.lastDate || 'saknas')}</small><button class="row-action" data-action="nav" data-page="bank">Öppna bankflöde →</button></article>` : `<article class="flow-health ok"><b>Bankflöde aktuellt</b><span>${escapeHtml(flowHealth.bank.message)}</span><small>Senaste import: ${escapeHtml(flowHealth.bank.lastDate || 'saknas')}</small></article>`, flowHealth.email.warning ? `<article class="flow-health warning"><b>Fakturamejl stannat</b><span>${escapeHtml(flowHealth.email.message)}</span><small>Senaste registrering: ${escapeHtml(flowHealth.email.lastDate || 'saknas')}</small><button class="row-action" data-action="nav" data-page="supplier">Öppna attestflöde →</button></article>` : `<article class="flow-health ok"><b>Fakturamejl aktuellt</b><span>${escapeHtml(flowHealth.email.message)}</span><small>Senaste registrering: ${escapeHtml(flowHealth.email.lastDate || 'saknas')}</small></article>`].join('');
  const action = `<div class="heading-date"><span class="live-dot"></span> ${date(F.localToday())}<button class="row-action" data-action="refresh">↻ Uppdatera</button></div>`;
  const priorities = d.priorities.slice(0,showAllPriorities ? undefined : 8).map((p,index) => { const reconciliation = p.kind === 'reconciliation'; const action = p.bankId ? 'review-tx' : reconciliation ? 'ledger-reconcile' : 'res-detail'; return `<li class="priority-row"><span class="priority-number ${p.rank <= 2 ? 'urgent' : ''}">${String(index+1).padStart(2,'0')}</span><div><b>${escapeHtml(p.label)}</b><p>${escapeHtml(p.detail)}</p></div><strong>${money(p.amount)}</strong><button class="button ghost sm" data-action="${action}" data-id="${p.bankId || p.id || ''}" data-kind="${p.kind || ''}">Öppna <span aria-hidden="true">→</span></button></li>`; }).join('');
  const aging = F.aging(d.customers);
  const maxAging = Math.max(1,...aging.map(a=>a.value));
  const ageRows = aging.map((a,index) => `<button class="aging-row" data-action="drill" data-page="receivables" data-filter="age${index}"><span>${a.label}</span><div class="meter-track"><i style="width:${a.value/maxAging*100}%" class="${index ? 'warm' : ''}"></i></div><b>${money(a.value)}</b></button>`).join('');
  const trend = d.flow.map(f => `<tr><th scope="row">${f.label}</th><td class="number-cell incoming">${money(f.incoming)}</td><td class="number-cell">${money(f.outgoing)}</td><td class="number-cell"><b>${money(f.incoming-f.outgoing)}</b></td></tr>`).join('');
  const rec = d.reconciliations.map(r => `<div class="reconcile-row"><span>Konto ${r.account}<small>Reskontra ${money(r.subledger)} · Huvudbok ${money(r.ledger)}</small></span><b class="${r.difference ? 'negative' : 'incoming'}">${r.difference ? `Differens ${money(r.difference)}` : 'Avstämt ✓'}</b></div>`).join('');
  return workspaceChrome(`${supplierWarnings()}${heading('Din ekonomi. Samlad.', 'Följ läget, prioritera dagen och gå direkt till det som behöver göras.', action)}<section class="flow-health-grid" aria-label="Flödesövervakning">${flowWarnings}</section>
    <div class="quick-actions" aria-label="Snabbåtgärder"><button data-action="manual-payment">＋ Inbetalning utan fil</button><button data-action="new-invoice">＋ Skapa kundfaktura</button><button data-action="new-supplier">↓ Registrera inköp</button><button data-action="nav" data-page="bank">⇄ Importera bankfil</button><button data-action="nav" data-page="receivables">↗ Öppna kundreskontra</button><button data-action="nav" data-page="payables">↙ Öppna leverantörsreskontra</button></div>
    <section class="metrics command-metrics" aria-label="Ekonomiska nyckeltal">
      ${statCard('Kundfordringar', money(d.ar.open), `${d.customers.filter(i=>i.remaining>0).length} öppna fakturor`, 'receivables', 'open')}
      ${statCard('Leverantörsskulder', money(d.ap.open), 'Bokförda, obetalda fakturor', 'payables', 'open')}
      ${statCard('Förfallet från kunder', money(d.ar.overdue), 'Följ upp utestående betalningar', 'receivables', 'overdue', d.ar.overdue ? 'attention' : '')}
      ${statCard('Väntar på attest', money(d.ap.pending), 'Ej bokfört som leverantörsskuld', 'payables', 'pending')}
      ${statCard('Förfallet till leverantörer', money(d.ap.overdue), 'Kontrollera och planera betalning', 'payables', 'overdue', d.ap.overdue ? 'attention' : '')}
      ${statCard('Bankhändelser att granska', String(reviewCount()), 'Saknar slutförd avstämning', 'review', 'all', reviewCount() ? 'attention' : '')}
    </section>
    <div class="work-grid"><section class="panel priorities"><div class="panel-head"><div><span class="eyebrow">Ditt nästa steg</span><h2>Prioriterat idag <span class="count-chip">${count}</span></h2><p class="hint">Förfallna fakturor först, sedan bankavstämning och attest.</p></div></div><ol class="priority-list">${priorities || '<li class="empty">Inga utestående åtgärder. Alla poster är hanterade.</li>'}</ol>${count>8 ? `<button class="row-action" data-action="toggle-priorities">${showAllPriorities ? 'Visa färre' : 'Visa alla '+count+' åtgärder'} →</button>` : ''}</section>
    <section class="panel instruments"><span class="eyebrow">Kontrollpanelen</span><h2>Arbetsläget</h2><div class="completion"><div class="completion-value">${d.bankCount ? coverage+'<span>%</span>' : '—'}</div><div><b>Bankavstämning</b><p>${d.handled} av ${d.bankCount} händelser hanterade</p></div></div><progress max="100" value="${coverage}" aria-label="Andel bankhändelser avstämda"></progress><div class="instrument-values"><div><span>Bokförd intäkt · ${F.localToday().slice(0,7)}</span><b>${money(d.revenue)}</b></div><div><span>Bokförd kostnad · ${F.localToday().slice(0,7)}</span><b>${money(d.expense)}</b></div></div><p class="hint">Exklusive moms, från registrerade verifikationer. Äldre demounderlag är inte komplett.</p><button class="button ghost sm" data-action="nav" data-page="ledger">Öppna bokföring →</button></section></div>
    <div class="work-grid secondary-grid"><section class="panel"><div class="panel-head"><div><h2>Förväntat betalningsflöde</h2><p class="hint">Öppna bokförda fakturor, efter förfallodag. Ej banksaldo.</p></div></div><div class="table-wrap"><table class="flow-table"><thead><tr><th>Från idag</th><th class="align-right">In</th><th class="align-right">Ut</th><th class="align-right">Netto</th></tr></thead><tbody>${trend}</tbody></table></div><p class="hint">Förfallna poster och ej attesterade inköp ingår inte i prognosen.</p></section><section class="panel"><div class="panel-head"><div><h2>Ålder på kundfordringar</h2><p class="hint">Restbelopp efter förfallodag · SEK</p></div></div><div class="aging-list">${ageRows}</div></section></div>
    <div class="work-grid secondary-grid"><section class="panel"><div class="panel-head"><div><h2>Reskontra mot huvudbok</h2><p class="hint">Kontroll av registrerade saldon, inklusive tidigare poster.</p></div></div>${rec}<p class="hint">En differens kan bero på saknade ingående saldon eller äldre verifikationer. Kontrollera underlagen före avstämning.</p></section><section class="panel"><h2>Senaste aktivitet</h2><ul class="activity">${state.activity.slice(0,4).map(a=>`<li><time>${escapeHtml(a.time)}</time><span><i class="signal ${a.kind}"></i>${escapeHtml(a.text)}</span></li>`).join('')}</ul></section></div>`);
}

function partyDirectoryPage(kind) {
  const customer = kind === 'customer';
  const groups = F.partyDirectory(state, kind, directorySearch[kind]);
  const all = F.partyDirectory(state, kind);
  const open = all.reduce((n,g)=>n+g.open,0);
  const overdue = all.reduce((n,g)=>n+g.overdue,0);
  const pending = all.reduce((n,g)=>n+g.pending,0);
  const rows = groups.map(group => `<tr data-party-row><td><b>${escapeHtml(group.number || '—')}</b></td><td><b>${escapeHtml(group.party)}</b><br><span class="muted">${group.invoices.length} ${group.invoices.length===1?'faktura':'fakturor'}</span></td><td class="number-cell">${money(group.open)}</td><td class="number-cell ${group.overdue ? 'negative' : ''}">${money(group.overdue)}</td>${customer?'':`<td class="number-cell">${money(group.pending)}</td>`}<td>${group.latest ? date(group.latest) : '—'}</td><td class="align-right"><button class="row-action" data-action="party-ledger" data-kind="${kind}" data-party="${escapeHtml(group.party)}" data-party-number="${escapeHtml(group.number)}">Öppna reskontra →</button></td></tr>`).join('');
  return workspaceChrome(`${heading(customer?'Kunder':'Leverantörer', customer?'Samlad kundbild med öppna poster, förfallna belopp och direktlänk till kundreskontran.':'Samlad leverantörsbild med skulder, attestläge och direktlänk till leverantörsreskontran.', customer?'<button class="button" data-action="new-invoice">+ Ny kundfaktura</button>':'<button class="button" data-action="new-supplier">+ Ny leverantörsfaktura</button>')}<section class="metrics report-metrics directory-metrics"><article class="metric"><span>${customer?'Kunder':'Leverantörer'}</span><div class="number">${all.length}</div><small>Aktiva i reskontran</small></article><article class="metric"><span>${customer?'Kundfordringar':'Leverantörsskulder'}</span><div class="number">${money(open)}</div><small>Aktuellt restbelopp</small></article><article class="metric ${overdue?'attention':''}"><span>Förfallet</span><div class="number">${money(overdue)}</div><small>${overdue?'Kräver uppföljning':'Inget förfallet'}</small></article>${customer?'':`<article class="metric ${pending?'attention':''}"><span>Väntar på attest</span><div class="number">${money(pending)}</div><small>Ej bokfört som skuld</small></article>`}</section><section class="panel"><div class="directory-toolbar"><label>Sök ${customer?'kund':'leverantör'}<input type="search" data-directory-search="${kind}" value="${escapeHtml(directorySearch[kind])}" placeholder="Namn eller nummer"></label><span class="muted">${groups.length} träffar</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${customer?'Kundnr':'Leverantörsnr'}</th><th>${customer?'Kund':'Leverantör'}</th><th class="align-right">Öppet saldo</th><th class="align-right">Förfallet</th>${customer?'':'<th class="align-right">Ej attesterat</th>'}<th>Senaste faktura</th><th></th></tr></thead><tbody>${rows || `<tr><td colspan="${customer?6:7}" class="empty">Inga ${customer?'kunder':'leverantörer'} matchar sökningen.</td></tr>`}</tbody></table></div></section>`);
}
function invoiceInboxPage() {
  const pdfItems=(state.supplierInvoices||[]).filter(i=>/pdf|e-post|email/i.test(i.source||''));
  const pending=pdfItems.filter(i=>i.status==='Attest väntar').length;
  const recent=pdfItems.slice(0,8).map(i=>`<tr><td>${date(i.received)}</td><td><b>${escapeHtml(i.supplier)}</b><br><span class="muted">${escapeHtml(i.invoiceNumber)}</span></td><td>${escapeHtml(i.source||'PDF')}</td><td class="number-cell">${money(i.total)}</td><td>${status(i.status)}</td><td class="align-right"><button class="row-action" data-action="res-detail" data-kind="supplier" data-id="${i.id}">Öppna →</button></td></tr>`).join('');
  return workspaceChrome(`${heading('Fakturainkorg','Samla inkommande leverantörsfakturor från PDF och e-post i samma attestflöde.','<label class="button" for="supplier-pdf-file">+ Läs in PDF<input hidden id="supplier-pdf-file" type="file" accept="application/pdf,.pdf"></label>')}<section class="flow-health-grid inbox-health"><article class="flow-health ${state.settings?.lastInvoiceEmail?'ok':'warning'}"><b>Fakturamejl</b><span>${state.settings?.lastInvoiceEmail?'Senaste registrerade mejlflöde: '+state.settings.lastInvoiceEmail:'Microsoft 365/Graph är ännu inte anslutet i denna lokala version.'}</span><small>Inkorg: ${escapeHtml(state.settings?.emailInbox||'fakturor@demo.example.invalid')}</small></article><article class="flow-health ${pending?'warning':'ok'}"><b>Attestkö</b><span>${pending} PDF-fakturor väntar på attest.</span><small>Osäkra tolkningar ska alltid stanna för manuell kontroll.</small></article></section><div class="integration"><b>PDF-intag fungerar manuellt:</b> välj en PDF och registrera de kontrollerade uppgifterna i formuläret. Automatisk hämtning från e-post och AI/OCR kräver en produktionsanslutning och är därför inte låtsasaktiverad här.</div><section class="panel"><div class="panel-head"><div><h2>Senaste PDF-underlag</h2><p class="hint">Originalfilens namn sparas som källa när du läser in PDF manuellt.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mottagen</th><th>Leverantör</th><th>Källa</th><th class="align-right">Belopp</th><th>Status</th><th></th></tr></thead><tbody>${recent||'<tr><td colspan="6" class="empty">Inga PDF-underlag registrerade ännu.</td></tr>'}</tbody></table></div></section>`);
}
function reskontraPage(kind) {
  if(kind==='customer')return customerPortal();
  const customer = kind === 'customer';
  const f = ledgerFilters[kind];
  const all = F.items(state, kind);
  const list = F.items(state, kind, f);
  const sort = ledgerSort[kind];
  const sortValue = (item, key) => ({ party: item.party, partyNumber: item.partyNumber, aviNumber: item.aviNumber, invoiceDate: item.invoiceDate, invoiceAmount: item.total, due: item.dueDate, transactionDate: item.payments?.[0]?.date || '', transactionAmount: item.paidAmount, remaining: item.remaining, bookingType: item.credit ? 'Kreditfaktura' : item.booked ? 'Faktura' : 'Attest väntar' }[key] ?? '');
  list.sort((a,b) => { const av=sortValue(a,sort.key), bv=sortValue(b,sort.key); const an=typeof av==='number', bn=typeof bv==='number'; const cmp=an&&bn ? av-bv : String(av).localeCompare(String(bv),'sv',{numeric:true}); return sort.dir==='asc'?cmp:-cmp; });
  const total = F.totals(list);
  const parties = [...new Set(all.map(i=>i.party))].sort((a,b)=>a.localeCompare(b,'sv'));
  const partyNumbers = [...new Set(all.map(i=>i.partyNumber).filter(Boolean))].sort();
  const periods = [...new Set(all.map(i=>i.invoiceDate.slice(0,7)))].sort().reverse();
  const title = customer ? 'Kundreskontra' : 'Leverantörsreskontra';
  const options = [['all','Alla poster'],['open','Öppna'],['overdue','Förfallna'],['partial','Delbetalda'],['paid','Betalda'],['due','Förfaller inom 7 dagar'],...(!customer ? [['pending','Väntar på attest']] : []),['age0','Ej förfallna'],['age1','Förfallna 1–30 dagar'],['age2','Förfallna 31–60 dagar'],['age3','Förfallna 61–90 dagar'],['age4','Förfallna över 90 dagar']];
  const grouped = list.reduce((map, i) => { const key = customer ? `${i.partyNumber || '—'}|${i.party}` : i.party; (map[key] ||= []).push(i); return map; }, {});
  const visible = ledgerColumns[kind].map((show,index)=>show?index:null).filter(index=>index!==null);
  const groupRows = Object.values(grouped).map(items => { const first = items[0]; const invoiceRows = items.map(i => F.rows(i).map(r => `<tr class="${r.paymentId ? 'payment-line' : ''}" data-action="res-detail" data-kind="${kind}" data-id="${i.id}" tabindex="0" role="button">${F.values(r).map((v,index) => ledgerColumns[kind][index] ? `<td class="${[5,11,12].includes(index) ? 'number-cell' : ''}">${v == null || v === '' ? '<span class="muted">—</span>' : [5,11,12].includes(index) ? decimal(v) : escapeHtml(v)}</td>` : '').join('')}</tr>`).join('')).join(''); const rest = items.reduce((n, i) => n + i.remaining, 0); return `<tbody data-export-kind="${kind}" data-export-party="${escapeHtml(first.party)}" data-export-party-number="${escapeHtml(first.partyNumber || '')}"><tr class="invoice-group"><th colspan="${visible.length}"><div><span><b>${customer ? escapeHtml(first.partyNumber || '—') + ' · ' : ''}${escapeHtml(first.party)}</b><span class="muted"> · ${items.length} ${items.length === 1 ? 'faktura' : 'fakturor'}</span></span><span class="group-tools">Rest <b>${money(rest)}</b></span></div></th></tr>${invoiceRows}</tbody>`; }).join('');
  const headerKeys = ['invoiceDate','bookingType','method','aviNumber','invoiceDate','invoiceAmount','due','batch','transactionDate','bookingType','transactionNumber','transactionAmount','remaining'];
  const headers = F.headers.map((h,index) => { if (!ledgerColumns[kind][index]) return ''; const key=headerKeys[index]; const active=sort.key===key; return `<th scope="col"><button class="sort-heading" data-action="sort-res" data-kind="${kind}" data-key="${key}">${h}${active ? `<span aria-label="sorterad ${sort.dir==='asc'?'stigande':'fallande'}">${sort.dir==='asc'?'↑':'↓'}</span>` : ''}</button></th>`; }).join('');
  const picker = `<details class="column-picker"><summary>Välj kolumner</summary><div>${F.headers.map((h,index)=>`<label><input type="checkbox" data-column-toggle data-kind="${kind}" data-index="${index}" ${ledgerColumns[kind][index]?'checked':''}>${h}</label>`).join('')}</div></details>`;
  return workspaceChrome(`${supplierWarnings()}${heading(title, 'Fakturor, betalningar och restbelopp – samlade per motpart. Högerklicka på en kund- eller leverantörsgrupp för Excel-export.', `<button class="button" data-action="export-res" data-kind="${kind}">↓ Exportera urval</button>`)}
    <div class="res-tabs"><button class="${customer?'active':''}" data-action="nav" data-page="receivables">Kundreskontra</button><button class="${!customer?'active':''}" data-action="nav" data-page="payables">Leverantörsreskontra</button></div>
    <section class="metrics res-metrics"><article class="metric"><span class="label">Fakturerat, bokfört</span><div class="number">${money(total.invoiced)}</div><span class="sub">${list.filter(i=>i.booked).length} fakturor i urvalet</span></article><article class="metric"><span class="label">${customer?'Inbetalt':'Utbetalt'}</span><div class="number">${money(total.paid)}</div><span class="sub">Registrerade betalningar</span></article><article class="metric"><span class="label">Restbelopp</span><div class="number">${money(total.open)}</div><span class="sub">Öppna bokförda poster</span></article><article class="metric"><span class="label">Varav förfallet</span><div class="number ${total.overdue?'negative':''}">${money(total.overdue)}</div><span class="sub">Förfallodag före idag</span></article></section>
    <section class="panel res-panel"><form class="res-filters" data-form="res-filters" data-kind="${kind}"><label>Sök<input type="search" name="search" value="${escapeHtml(f.search)}" placeholder="Namn, faktura eller transaktion"></label>${customer ? `<label>Kundnummer<select name="partyNumber"><option value="">Alla kundnummer</option>${partyNumbers.map(p=>`<option ${f.partyNumber===p?'selected':''}>${escapeHtml(p)}</option>`).join('')}</select></label>` : ''}<label>${customer?'Bolag':'Leverantör'}<select name="party"><option value="">Alla ${customer?'bolag':'leverantörer'}</option>${parties.map(p=>`<option ${f.party===p?'selected':''} value="${escapeHtml(p)}">${escapeHtml(p)}</option>`).join('')}</select></label><label>Fakturaperiod<select name="period"><option value="">Alla perioder</option>${periods.map(p=>`<option ${f.period===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Status<select name="status">${options.map(([v,l])=>`<option value="${v}" ${f.status===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="button" type="submit">Visa urval</button><button type="button" class="row-action" data-action="reset-res" data-kind="${kind}">Nollställ</button></form>
    <div class="res-summary" aria-live="polite"><span>${list.length} fakturor · ${new Set(list.map(i=>i.party)).size} ${customer?'kunder':'leverantörer'} · Alla belopp i SEK</span>${total.pending ? `<span>Ej attesterat: <b>${money(total.pending)}</b> (utanför bokfört saldo)</span>` : ''}</div>${picker}<div class="table-wrap res-scroll" tabindex="0" role="region" aria-label="${title}, bläddra i sidled för alla kolumner"><table class="data-table res-table"><thead><tr>${headers}</tr></thead>${groupRows || `<tbody><tr><td class="empty" colspan="${visible.length}">Inga poster matchar ditt urval. Prova att nollställa filtren.</td></tbody>`}</table></div><div class="res-footnotes"><span>Ffd = förfallodag. Buntnr = import- eller betalningsbunt. Transnr = verifikation eller bankreferens.</span><span>Betalningar visas med minustecken. Restbeloppet visar fakturans aktuella saldo på samtliga rader. Saknade historiska uppgifter visas som —.</span><span>Periodfiltret väljer fakturaperiod; alla registrerade betalningar till valda fakturor visas.</span></div></section>`);
}

function resDetail(kind, id) {
  const i = F.items(state,kind).find(i=>i.id===id);
  if (!i) return '';
  const payments = i.payments.map(p=>`<li><span>${p.date || 'Datum saknas'}<small>${p.reclassified ? 'Omförd till ' + escapeHtml(p.reclassifiedTo) + ' · ny bunt ' + escapeHtml(p.reclassificationBatch) + ' · ' : ''}${p.reversed ? 'Återförd · ' : ''}${escapeHtml(p.method || '')} · ${escapeHtml(p.reference || p.source || '')}${p.journalNumber?' · '+escapeHtml(p.journalNumber):''}${p.reversalJournalNumber?' · mot '+escapeHtml(p.reversalJournalNumber):''}</small></span><span><b>${money(p.amount)}</b>${p.reversed || p.reclassified || p.reclassifiedFrom ? '' : ` <button class="row-action" data-action="reverse-payment-modal" data-kind="${kind}" data-id="${i.id}" data-payment-id="${p.id}" data-entry-type="payment">Återför</button>`}</span></li>`).join('');
  const payouts = (i.payouts || []).map(p=>`<li><span>${p.date || 'Datum saknas'}<small>${p.reclassified ? 'Omförd till ' + escapeHtml(p.reclassifiedTo) + ' · ny bunt ' + escapeHtml(p.reclassificationBatch) + ' · ' : ''}${p.reversed ? 'Återförd · ' : ''}${escapeHtml(p.method || '')} · ${escapeHtml(p.reference || '')}${p.journalNumber?' · '+escapeHtml(p.journalNumber):''}${p.reversalJournalNumber?' · mot '+escapeHtml(p.reversalJournalNumber):''}</small></span><span><b>−${money(p.amount)}</b>${p.reversed || p.reclassified || p.reclassifiedFrom ? '' : ` <button class="row-action" data-action="reverse-payment-modal" data-kind="${kind}" data-id="${i.id}" data-payment-id="${p.id}" data-entry-type="payout">Återför</button>`}</span></li>`).join('');
  const journal = (state.journal || []).find(entry => entry.number === i.journalNumber) || (state.journal || []).find(entry => /faktura/i.test(entry.source || '') && String(entry.description || '').includes(F.invoiceNumber(i)));
  const postings = journal ? journal.rows.map(row=>`<tr><td>${escapeHtml(row.account)}</td><td class="number-cell">${row.debit ? money(row.debit) : '—'}</td><td class="number-cell">${row.credit ? money(row.credit) : '—'}</td></tr>`).join('') : '<tr><td colspan="3" class="muted">Ingen kontering hittades i journalen.</td></tr>';
  const batchInfo = `<div class="detail-row"><span>Bokföringsdag / buntnummer</span><b>${escapeHtml(i.postingDate || i.bookedDate || '—')} · ${escapeHtml(i.batchNumber || i.batch || (journal?.batchNumber || '—'))}</b></div>`;
  const credits = kind === 'customer' && !i.credit ? F.items(state,'customer').filter(c => c.remaining < 0 && c.id !== i.id && c.partyNumber === i.partyNumber && c.party === i.party) : [];
  const actions = !i.booked ? `<button class="button" data-action="approve-res" data-id="${i.id}">Attestera & bokför</button>` : (i.remaining<0 && kind==='customer' ? `<button class="button" data-action="payout-modal" data-kind="${kind}" data-id="${i.id}">Återbetala till kund</button>` : (!i.credit && (i.remaining>0 || kind==='customer') ? `<button class="button" data-action="payment-modal" data-kind="${kind}" data-id="${i.id}">Registrera ${kind==='customer'?'inbetalning':'utbetalning'}</button>` : ''));
  return modalShell('Faktura '+i.aviNumber, `<div class="detail-intro"><div><b>${customerLabel(i)}</b><p>${escapeHtml(i.reference || i.suggestedAccount || '')}</p></div>${status(i.status)}</div><div class="detail-totals"><div><span>Fakturabelopp</span><b>${money(i.total)}</b></div><div><span>${kind==='customer'?'Inbetalt':'Utbetalt'}</span><b>${money(i.paidAmount)}</b></div><div><span>Återstår</span><b>${money(i.remaining)}</b></div></div><div class="review-detail"><div class="detail-row"><span>Fakturadatum / förfallodag</span><b>${i.invoiceDate} / ${i.dueDate}</b></div><div class="detail-row"><span>Verifikation</span><b>${escapeHtml(i.journalNumber || 'Saknas i tidigare underlag')}</b></div></div>${batchInfo}<h3 class="detail-subheading">Exakt kontering</h3><div class="table-wrap posting-detail"><table class="data-table"><thead><tr><th>Konto</th><th class="align-right">Debet</th><th class="align-right">Kredit</th></tr></thead><tbody>${postings}</tbody></table></div><h3 class="detail-subheading">Betalningshistorik</h3><ul class="payment-history">${payments || '<li class="muted">Inga betalningar registrerade.</li>'}${payouts}</ul>${credits.length && i.remaining>0 ? `<div class="offset-box"><b>Kreditfakturor och överbetalningar</b><p class="hint">Kvitta ett kreditbelopp mot denna öppna faktura.</p>${credits.map(c=>`<button class="row-action" data-action="offset-modal" data-id="${i.id}" data-credit-id="${c.id}">${c.aviNumber} · ${money(Math.abs(c.remaining))} kr → Kvitta</button>`).join('')}</div>` : ''}<div class="modal-foot">${kind==='customer' ? `<button class="button" data-action="pdf-invoice" data-id="${i.id}">Öppna / skriv ut PDF</button>` : ''}${actions}${i.remaining>0 && !i.credit ? `<button class="button ghost" data-action="writeoff-modal" data-kind="${kind}" data-id="${i.id}">Boka ut post</button>` : ''}<button class="button ghost" data-action="close-modal">Stäng</button></div>`);
}
function batchesPage() {
  const query = String(batchSearch || '').toLocaleLowerCase('sv');
  const entries = (state.journal || []).filter(entry => !query || String(entry.batchNumber || entry.batch || '').toLocaleLowerCase('sv').includes(query));
  const rows = entries.map(entry => `<tr data-action="batch-detail" data-id="${entry.id}" tabindex="0" role="button"><td><b>${escapeHtml(entry.batchNumber || entry.batch || '—')}</b></td><td>${escapeHtml(entry.postingDate || entry.date || '')}</td><td>${escapeHtml(entry.number || '')}</td><td>${escapeHtml(entry.description || '')}</td><td>${escapeHtml(entry.source || '')}</td></tr>`).join('');
  return adminChrome(`${heading('Buntar','Varje bokföringsunderlag får automatiskt ett fyrsiffrigt buntnummer. Sök på buntnummer för att se hela verifikationen.')}<form data-form="batch-search" class="ledger-toolbar"><label>Sök buntnummer<input name="query" inputmode="numeric" value="${escapeHtml(batchSearch)}" placeholder="Ex. 1007"></label><button class="button" type="submit">Sök</button><button class="button ghost" type="button" data-action="clear-batch-search">Visa alla</button></form><div class="integration">Buntnumret följer underlaget från faktura, betalning, kvittning, omföring, bankavstämning och motverifikation. Bokföringsdagen visas separat och kan väljas när underlaget skapas.</div><article class="panel table-wrap"><table class="data-table"><thead><tr><th>Buntnr</th><th>Bokföringsdag</th><th>Verifikation</th><th>Vad bunten avser</th><th>Källa</th></tr></thead><tbody>${rows || '<tr><td colspan="5" class="empty">Inga buntar matchar sökningen.</td></tr>'}</tbody></table></article>`);
}
function batchDetail(id) {
  const entry = (state.journal || []).find(item => item.id === id);
  if (!entry) return '';
  const rows = (entry.rows || []).map(row => `<tr><td>${escapeHtml(row.account || '')}<br><small>${escapeHtml(row.description || '')} ${escapeHtml(row.customerNumber || '')}</small></td><td class="number-cell">${row.debit ? money(row.debit) : '—'}</td><td class="number-cell">${row.credit ? money(row.credit) : '—'}</td></tr>`).join('');
  return modalShell(`Bunt ${entry.batchNumber || entry.batch || '—'}`, `<div class="detail-intro"><div><b>${escapeHtml(entry.description || '')}</b><p>${escapeHtml(entry.source || '')} · Verifikation ${escapeHtml(entry.number || '')}</p></div><span class="status booked">Bokförd</span></div><div class="review-detail"><div class="detail-row"><span>Buntnummer</span><b>${escapeHtml(entry.batchNumber || entry.batch || '—')}</b></div><div class="detail-row"><span>Bokföringsdag</span><b>${escapeHtml(entry.postingDate || entry.date || '')}</b></div><div class="detail-row"><span>Avser</span><b>${escapeHtml(entry.source || 'Manuell bokning')}</b></div></div><h3 class="detail-subheading">Fullständig kontering</h3><div class="table-wrap posting-detail"><table class="data-table"><thead><tr><th>Konto</th><th class="align-right">Debet</th><th class="align-right">Kredit</th></tr></thead><tbody>${rows}</tbody></table></div><div class="modal-foot"><button class="button ghost" data-action="close-modal">Stäng</button></div>`);
}
function customerLabel(i) { return `${i.partyNumber ? escapeHtml(i.partyNumber) + ' · ' : ''}${escapeHtml(i.party)}`; }
function modalShell(title, body) {
  return `<div class="modal-backdrop" data-action="close-modal"><section class="modal workspace-modal" role="dialog" aria-modal="true" aria-labelledby="workspace-dialog-title" data-stop><div class="modal-header"><h2 id="workspace-dialog-title">${escapeHtml(title)}</h2><button data-action="close-modal" aria-label="Stäng">×</button></div><div class="modal-body">${body}</div></section></div>`;
}
function workspaceModal() {
  if (activeModal?.type === 'receivables-confirm') return receivablesConfirmation();
  if(activeModal?.type==='manual-payment')return manualPaymentChooser();
  if(activeModal?.type==='credit-menu') {
    const credit=F.items(state,'customer').find(x=>x.id===activeModal.id);
    if(!credit)return '';
    const candidates=F.items(state,'customer').filter(x=>x.id!==credit.id && x.remaining>0 && x.partyNumber===credit.partyNumber && x.party===credit.party);
    return modalShell('Kreditbelopp – välj åtgärd', `<p><b>${customerLabel(credit)}</b> · ${escapeHtml(credit.aviNumber)}<br>Disponibelt tillgodo: <b>${money(Math.abs(credit.remaining))}</b></p><p class="hint">Kvittning kan bara göras mot en faktura från samma kund. Alla belopp är hela kronor.</p><div class="credit-actions">${candidates.map(i=>`<button class="row-action" data-action="offset-modal" data-id="${i.id}" data-credit-id="${credit.id}">Kvitta mot ${escapeHtml(i.aviNumber)} · rest ${money(i.remaining)}</button>`).join('') || '<p class="empty">Ingen öppen faktura från samma kund hittades.</p>'}<button class="button ghost" data-action="payout-modal" data-kind="customer" data-id="${credit.id}">Återbetala till kunden</button><button class="button ghost" data-action="close-modal">Avbryt</button></div>`);
  }
  if (activeModal?.type === 'resDetail') return resDetail(activeModal.kind,activeModal.id);
  if (activeModal?.type === 'batchDetail') return batchDetail(activeModal.id);
  if (activeModal?.type === 'supplier-approve') {
    const invoice = state.supplierInvoices.find(item => item.id === activeModal.id);
    if (!invoice) return '';
    return modalShell('Attestera leverantörsfaktura', `<p><b>${escapeHtml(invoice.supplier)}</b> · ${escapeHtml(invoice.invoiceNumber)}<br>Belopp: <b>${money(invoice.total)}</b></p><p class="hint">Välj bokföringsdag. Dagens datum är ifyllt och kan ändras till en annan öppen dag.</p><form data-form="supplier-approve"><input type="hidden" name="id" value="${invoice.id}"><label class="field">Bokföringsdag<input name="postingDate" type="date" max="${F.localToday()}" value="${F.localToday()}" required></label><p class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Avbryt</button><button class="button" type="submit">Attestera & bokför</button></div></form>`);
  }
  if (activeModal?.type === 'payment') {
    const i = F.items(state,activeModal.kind).find(i=>i.id===activeModal.id);
    if (!i) return '';
    return modalShell('Registrera betalning', `<p><b>${escapeHtml(i.party)}</b> · ${escapeHtml(i.aviNumber)}<br>Restbelopp: <b>${money(i.remaining)}</b></p><p class="hint">Registrera en redan genomförd bankbetalning. Kundöverbetalningar sparas som negativt restbelopp. Alla belopp anges i hela kronor.</p><form data-form="payment" class="payment-form"><input type="hidden" name="kind" value="${activeModal.kind}"><input type="hidden" name="invoiceId" value="${i.id}"><input type="hidden" name="idempotencyKey" value="${activeModal.key}"><div class="form-grid"><label class="field">Belopp (SEK)<input name="amount" type="number" step="1" min="1" ${activeModal.kind==='supplier'?`max="${i.remaining}"`:''} value="${Math.max(1,Math.round(i.remaining))}" required></label><label class="field">Bokföringsdatum<input name="date" type="date" min="${i.invoiceDate}" max="${F.localToday()}" value="${F.localToday()}" required></label><label class="field">Betalsätt<select name="method"><option>Bank</option><option>Bankgiro</option><option>Swish</option></select></label><label class="field">Buntnummer (valfritt)<input name="batch" maxlength="100" placeholder="Ex. SEP-01"></label><label class="field full">Unik bankreferens<input name="reference" maxlength="150" required placeholder="Referens från den genomförda betalningen"></label></div><p class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="button ghost" data-action="res-detail" data-kind="${activeModal.kind}" data-id="${i.id}">Tillbaka</button><button class="button" type="submit">Registrera & bokför</button></div></form>`);
  }
  if (activeModal?.type === 'payout') {
    const i=F.items(state,activeModal.kind).find(x=>x.id===activeModal.id); if(!i)return '';
    const max=activeModal.kind==='customer'?Math.abs(Math.min(0,i.remaining)):i.remaining;
    return modalShell(activeModal.kind==='customer'?'Återbetala kund':'Registrera utbetalning', `<p><b>${escapeHtml(i.party)}</b> · ${escapeHtml(i.aviNumber)}<br>Disponibelt belopp: <b>${money(max)}</b></p><p class="hint">Utbetalningen bokförs med debet på ${activeModal.kind==='customer'?'1510 Kundfordringar':'2440 Leverantörsskulder'} och kredit på 1930. Alla belopp är hela kronor.</p><form data-form="payout"><input type="hidden" name="kind" value="${activeModal.kind}"><input type="hidden" name="invoiceId" value="${i.id}"><label class="field">Belopp<input name="amount" type="number" step="1" min="1" max="${Math.max(1,Math.round(max))}" value="${Math.max(1,Math.round(max))}" required></label><label class="field">Utbetalningsdatum<input name="date" type="date" min="${i.invoiceDate}" max="${F.localToday()}" value="${F.localToday()}" required></label><label class="field">Betalsätt<select name="method"><option>Bank</option><option>Bankgiro</option><option>Swish</option></select></label><label class="field">Buntnummer (valfritt)<input name="batch"></label><label class="field">Unik betalningsreferens<input name="reference" required placeholder="Ex. RETUR-2026-01"></label><label class="field">Orsak<textarea name="reason" rows="2" placeholder="Ex. återbetalning av överinbetalning"></textarea></label><p class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="button ghost" data-action="res-detail" data-kind="${activeModal.kind}" data-id="${i.id}">Tillbaka</button><button class="button" type="submit">Bokför utbetalning</button></div></form>`);
  }
  if (activeModal?.type === 'reverse-payment') {
    const i=F.items(state,activeModal.kind).find(x=>x.id===activeModal.id); if(!i)return '';
    return modalShell('Återför betalning med motverifikation', `<p><b>${escapeHtml(i.party)}</b> · ${escapeHtml(i.aviNumber)}</p><p class="hint">Originalverifikationen ändras inte. En ny, balanserad motverifikation skapas i en öppen period och betalningen markeras som återförd.</p><form data-form="reverse-payment"><input type="hidden" name="kind" value="${activeModal.kind}"><input type="hidden" name="invoiceId" value="${i.id}"><input type="hidden" name="paymentId" value="${activeModal.paymentId}"><input type="hidden" name="entryType" value="${activeModal.entryType}"><label class="field">Motverifikationsdatum<input name="date" type="date" max="${F.localToday()}" value="${F.localToday()}" required></label><label class="field">Orsak<textarea name="reason" rows="3" required placeholder="Ex. Felregistrerad betalning – ersätts av bankrad ..."></textarea></label><p class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="button ghost" data-action="res-detail" data-kind="${activeModal.kind}" data-id="${i.id}">Avbryt</button><button class="button" type="submit">Skapa motverifikation</button></div></form>`);
  }
  if (activeModal?.type === 'search') return modalShell('Sök i plattformen', `<label class="field">Kund, leverantör, fakturanummer eller sida<input id="platform-search" type="search" placeholder="Skriv för att söka…" value="${escapeHtml(quickSearch)}" autocomplete="off"></label><div id="search-results" class="search-results" aria-live="polite">${searchResults()}</div>`);
  if (activeModal?.type === 'offset') { const i=F.items(state,'customer').find(x=>x.id===activeModal.id), c=F.items(state,'customer').find(x=>x.id===activeModal.creditId); if(!i||!c) return ''; const max=Math.min(i.remaining,Math.abs(c.remaining)); return modalShell('Kvitta kreditfaktura', `<p>${customerLabel(c)} · ${c.aviNumber} mot ${i.aviNumber}</p><form data-form="offset"><input type="hidden" name="creditInvoiceId" value="${c.id}"><input type="hidden" name="invoiceId" value="${i.id}"><label class="field">Belopp att kvitta<input name="amount" type="number" min="1" max="${max}" step="1" value="${max}" required></label><label class="field">Bokföringsdag<input type="date" name="date" value="${F.localToday()}" max="${F.localToday()}" required></label><input type="hidden" name="idempotencyKey" value="${activeModal.key ||= crypto.randomUUID()}"><p class="hint">Skapar en balanserad kvittningsverifikation på konto 1510.</p><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Avbryt</button><button class="button" type="submit">Kvitta & bokför</button></div></form>`); }
  if (activeModal?.type === 'writeoff') { return modalShell('Boka ut post', `<p>Restbelopp: <b>${money(activeModal.remaining)} kr</b></p><form data-form="writeoff"><input type="hidden" name="kind" value="${activeModal.kind}"><input type="hidden" name="invoiceId" value="${activeModal.id}"><label class="field">Orsak<textarea name="reason" rows="3" required placeholder="Ex. Felregistrerad faktura, ersatt av ..."></textarea></label><label class="field">Resultatkonto<select name="account"><option>${activeModal.kind==='customer'?'6351 Kundförluster':'6990 Övriga externa kostnader'}</option><option>6990 Övriga externa kostnader</option><option>6071 Representation</option></select></label><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Avbryt</button><button class="button" type="submit">Boka ut & skapa verifikation</button></div></form>`); }
  return null;
}
function searchResults() {
  const term = quickSearch.toLocaleLowerCase('sv');
  const destinations = [['overview','Översikt'],['receivables','Kundreskontra'],['res-tools','Reskontraverktyg'],['payables','Leverantörsreskontra'],['bank','Bank & avstämning'],['ledger','Bokföring'],['batches','Buntar'],['accounts','Kontoplan'],['reports','Rapporter'],['audit','Revisionslogg'],['assistant','Hjälp & chatbot'],['review','Granska & åtgärda']];
  const links = destinations.filter(([k,l])=>l.toLocaleLowerCase('sv').includes(term)).map(([k,l])=>`<button data-action="nav" data-page="${k}"><b>${l}</b><span>Gå till sida →</span></button>`);
  const list = term ? [...F.items(state,'customer',{search:term}),...F.items(state,'supplier',{search:term})].slice(0,15).map(i=>`<button data-action="res-detail" data-kind="${i.kind}" data-id="${i.id}"><span><b>${escapeHtml(i.party)}</b><small>${i.kind==='customer'?'Kund':'Leverantör'} · ${escapeHtml(i.aviNumber)}</small></span><span>${money(i.remaining)} kvar →</span></button>`) : [];
  return [...links,...list].join('') || '<p class="empty">Inga träffar.</p>';
}

document.addEventListener('click', async e => {
  const b = e.target.closest('[data-action]'); if (!b) return;
  const a = b.dataset.action;
  if (a === 'toggle-priorities') { showAllPriorities=!showAllPriorities; render(); }
  if (a === 'toggle-nav') { navOpen = !navOpen; render(); }
  if (a === 'party-ledger') { const kind=b.dataset.kind; const key=kind==='customer'?'customer':'supplier'; ledgerFilters[key]={status:'all',period:'',party:b.dataset.party||'',partyNumber:b.dataset.partyNumber||'',search:''}; navigate(kind==='customer'?'receivables':'payables'); }
  if (a === 'ledger-tab') { ledgerSection = b.dataset.tab || 'journal'; render(); }
  if (a === 'clear-account-plan-search') { accountPlanQuery = ''; render(); }
  if (a === 'ledger-reconcile') { page = 'ledger'; view = 'admin'; ledgerSection = 'reconcile'; activeModal = null; navOpen = false; if (location.hash !== '#/ledger') history.pushState(null, '', '#/ledger'); render(); window.scrollTo({ top: 0, behavior: 'instant' }); }
  if (a === 'clear-ledger-search') { ledgerSearch = ''; render(); }
  if (a === 'drill') navigate(b.dataset.page,b.dataset.filter);
  if (a === 'res-detail') { activeModal = { type:'resDetail', kind:b.dataset.kind, id:b.dataset.id }; render(); }
  if (a === 'batch-detail') { activeModal = { type:'batchDetail', id:b.dataset.id }; render(); }
  if (a === 'clear-batch-search') { batchSearch = ''; render(); }
  if (a === 'payment-modal') { activeModal = { type:'payment', kind:b.dataset.kind, id:b.dataset.id, key:crypto.randomUUID() }; render(); }
  if (a === 'offset-modal') { activeModal = { type:'offset', id:b.dataset.id, creditId:b.dataset.creditId }; render(); }
  if (a === 'payout-modal') { activeModal = { type:'payout', kind:b.dataset.kind || 'customer', id:b.dataset.id }; render(); }
  if (a === 'writeoff-modal') { const i=F.items(state,b.dataset.kind).find(x=>x.id===b.dataset.id); activeModal = { type:'writeoff', kind:b.dataset.kind, id:b.dataset.id, remaining:i?.remaining || 0 }; render(); }
  if (a === 'reverse-payment-modal') { activeModal = { type:'reverse-payment', kind:b.dataset.kind, id:b.dataset.id, paymentId:b.dataset.paymentId, entryType:b.dataset.entryType || 'payment' }; render(); }
  if (a === 'sort-res') { const s=ledgerSort[b.dataset.kind] || (ledgerSort[b.dataset.kind]={key:'invoiceDate',dir:'desc'}); s.dir=s.key===b.dataset.key&&s.dir==='asc'?'desc':'asc'; s.key=b.dataset.key; render(); }
  if (a === 'close-context-menu') { activeContextMenu=null; render(); }
  if (a === 'export-context') { const p={kind:b.dataset.kind,party:b.dataset.party||'',partyNumber:b.dataset.partyNumber||''}; activeContextMenu=null; window.location.href=(p.kind==='ledger' ? '/api/export/excel' : '/api/export/reskontra?'+new URLSearchParams(p)); }
  if (a === 'period-unlock') { try { const data=await api('/api/period-locks',{method:'POST',body:{period:b.dataset.period,action:'unlock'}}); syncStore(data); toast(`Period ${b.dataset.period} är upplåst.`); } catch(error) { toast(error.message); } }
  if (a === 'reset-res') { ledgerFilters[b.dataset.kind] = {status:'all',period:'',party:'',partyNumber:'',search:''}; render(); }
  if (a === 'export-res') window.location.href = '/api/export/reskontra?' + new URLSearchParams({kind:b.dataset.kind,...ledgerFilters[b.dataset.kind]});
  if (a === 'global-search') { activeModal = {type:'search'}; quickSearch = ''; render(); document.getElementById('platform-search')?.focus(); }
  if (a === 'refresh') { try { syncStore(await api('/api/state')); toast('Uppgifterna är uppdaterade.'); } catch(error) { toast(error.message); } }
  if (a === 'invoice-filter') { invoiceFilter = b.dataset.filter; render(); }
  if (a === 'approve-supplier-modal') { activeModal = { type:'supplier-approve', id:b.dataset.id }; render(); }
  if (a === 'approve-res') {
    b.disabled = true;
    try { const data = await api('/api/supplier-invoices/approve',{method:'POST',body:{id:b.dataset.id}}); syncStore(data); toast('Attesterad. Leverantörsreskontran är uppdaterad.'); } catch(error) { toast(error.message); b.disabled = false; }
  }
});
document.addEventListener('submit', async e => {
  const form = e.target;
  if (form.dataset.form === 'res-filters') { e.preventDefault(); ledgerFilters[form.dataset.kind] = Object.fromEntries(new FormData(form)); render(); }
  if (form.dataset.form === 'ledger-search') { e.preventDefault(); ledgerSearch = String(new FormData(form).get('query') || '').trim(); render(); }
  if (form.dataset.form === 'account-plan-search') { e.preventDefault(); accountPlanQuery = String(new FormData(form).get('query') || '').trim(); render(); }
  if (form.dataset.form === 'batch-search') { e.preventDefault(); batchSearch = String(new FormData(form).get('query') || '').trim(); render(); }
  if (form.dataset.form === 'payment') {
    e.preventDefault();
    const submit = form.querySelector('[type="submit"]'); submit.disabled = true;
    const values = Object.fromEntries(new FormData(form));
    try {
      const data = await api('/api/payments',{method:'POST',body:values});
      activeModal = {type:'resDetail',kind:values.kind,id:values.invoiceId}; syncStore(data); toast('Betalningen är bokförd och restbeloppet uppdaterat.');
    } catch(error) { form.querySelector('.form-error').textContent = error.message; submit.disabled = false; }
  }
  if (form.dataset.form === 'payout') { e.preventDefault(); try { const values=Object.fromEntries(new FormData(form)); const data=await api('/api/payouts',{method:'POST',body:values}); activeModal={type:'resDetail',kind:values.kind,id:values.invoiceId}; syncStore(data); toast('Utbetalningen är bokförd och verifikationen skapad.'); } catch(error) { form.querySelector('.form-error').textContent=error.message; } }
  if (form.dataset.form === 'offset') { e.preventDefault(); try { const data=await api('/api/receivables/offset',{method:'POST',body:Object.fromEntries(new FormData(form))}); activeModal={type:'resDetail',kind:'customer',id:form.querySelector('[name="invoiceId"]').value}; syncStore(data); toast('Kreditfakturan är kvittad och verifikationen skapad.'); } catch(error) { toast(error.message); } }
  if (form.dataset.form === 'writeoff') { e.preventDefault(); try { const data=await api('/api/invoices/writeoff',{method:'POST',body:Object.fromEntries(new FormData(form))}); activeModal=null; syncStore(data); toast('Posten är utbokad och verifikationen skapad.'); } catch(error) { toast(error.message); } }
  if (form.dataset.form === 'reverse-payment') { e.preventDefault(); const submit=form.querySelector('[type="submit"]'); submit.disabled=true; try { const values=Object.fromEntries(new FormData(form)); const data=await api('/api/payments/reverse',{method:'POST',body:values}); activeModal={type:'resDetail',kind:values.kind,id:values.invoiceId}; syncStore(data); toast('Motverifikationen är skapad och originalbetalningen är återförd.'); } catch(error) { form.querySelector('.form-error').textContent=error.message; submit.disabled=false; } }
  if (form.dataset.form === 'settings') { e.preventDefault(); try { const data=await api('/api/settings',{method:'POST',body:Object.fromEntries(new FormData(form))}); syncStore(data); toast('Kontrollinställningarna är sparade.'); } catch(error) { toast(error.message); } }
  if (form.dataset.form === 'supplier-approve') { e.preventDefault(); try { const values=Object.fromEntries(new FormData(form)); const data=await api('/api/supplier-invoices/approve',{method:'POST',body:values}); activeModal=null; syncStore(data); toast('Attesterad och bokförd med valt bokföringsdatum.'); } catch(error) { form.querySelector('.form-error').textContent=error.message; } }
  if (form.dataset.form === 'period-lock') { e.preventDefault(); try { const values=Object.fromEntries(new FormData(form)); const data=await api('/api/period-locks',{method:'POST',body:{period:values.period,action:'lock'}}); syncStore(data); toast(`Period ${values.period} är låst.`); } catch(error) { toast(error.message); } }
});
document.addEventListener('input', e => {
  if (e.target.id === 'platform-search') { quickSearch = e.target.value; document.getElementById('search-results').innerHTML = searchResults(); }
});
document.addEventListener('change', e => {
  if (e.target.matches('[data-column-toggle]')) { ledgerColumns[e.target.dataset.kind][Number(e.target.dataset.index)] = e.target.checked; render(); }
});
document.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k' && view === 'admin') { e.preventDefault(); activeModal={type:'search'}; quickSearch=''; render(); document.getElementById('platform-search')?.focus(); }
  if (e.key === 'Escape' && activeModal) { activeModal=null; render(); }
  if (e.key === 'Tab' && activeModal) {
    const controls = [...document.querySelectorAll('.modal button, .modal input:not([type=hidden]), .modal select, .modal textarea, .modal a[href]')].filter(el=>!el.disabled);
    const first = controls[0], last = controls.at(-1);
    if (e.shiftKey && document.activeElement===first) { e.preventDefault(); last?.focus(); }
    else if (!e.shiftKey && document.activeElement===last) { e.preventDefault(); first?.focus(); }
  }
});
window.addEventListener('popstate', () => { const destination=location.hash.slice(2); view=destination==='website'?'public':'admin'; page=destination||'overview'; activeModal=null; if(state) render(); });
document.addEventListener('contextmenu', e => {
  const row=e.target.closest('[data-export-kind]');
  if(!row || row.dataset.creditInvoice === 'true') return;
  e.preventDefault();
  activeContextMenu={kind:row.dataset.exportKind,party:row.dataset.exportParty,partyNumber:row.dataset.exportPartyNumber,x:Math.min(e.clientX,window.innerWidth-260),y:Math.min(e.clientY,window.innerHeight-90)};
  render();
});

document.addEventListener('input', event => {
  const kind = event.target?.dataset?.directorySearch;
  if (!kind || !(kind in directorySearch)) return;
  directorySearch[kind] = event.target.value;
  const term = event.target.value.toLocaleLowerCase('sv');
  document.querySelectorAll('[data-party-row]').forEach(row => { row.hidden = !row.textContent.toLocaleLowerCase('sv').includes(term); });
});
